//! Preserve each driver's SDK timer and normalize its output afterward.
use serde_json::Value;use std::{fs,path::Path,process::{Command,Stdio}};
fn main(){let a:Vec<_>=std::env::args_os().collect();assert_eq!(a.len(),5);let engine=std::env::var("ZOPRO_LB_ENGINE").unwrap();let dir=Path::new(&a[4]);fs::create_dir_all(dir).unwrap();let workers=std::env::var("RAYON_NUM_THREADS").unwrap();let mut child=if engine=="aeglos"{let stem=Path::new(&a[1]).file_stem().unwrap().to_str().unwrap();let mut c=Command::new("/usr/local/bin/aeglos-ablation");c.args(["aeglos",&format!("/gnark-keys/{stem}.key")]).args([&a[2],&a[3]]);c.env("ZOPRO_BENCH_PROOFS",dir.parent().unwrap()).env("AEGLOS_BENCH_DISABLE_SHIFTED","0").env("AEGLOS_CPU_THREADS",&workers).env("GOMAXPROCS",&workers);for(from,to)in[("ZOPRO_BENCH_PERF_CTL","CROSS_PERF_CTL"),("ZOPRO_BENCH_PERF_ACK","CROSS_PERF_ACK")]{if let Some(v)=std::env::var_os(from){c.env(to,v);}}c}else{assert!(matches!(engine.as_str(),"accepted"|"off"|"on"));let mut c=Command::new(if engine=="accepted"{"/usr/local/bin/lb-accepted"}else{"/usr/local/bin/lb-candidate"});c.args(&a[1..]).env("ZOPRO_CPU_GROUPING_LOWER_BOUND",if engine=="on"{"1"}else{"0"});c};child.stdout(Stdio::from(fs::File::create(dir.join("driver.stdout")).unwrap())).stderr(Stdio::from(fs::File::create(dir.join("driver.stderr")).unwrap()));assert!(child.status().unwrap().success(),"SDK failed");let output=fs::read_to_string(dir.join("driver.stdout")).unwrap();let mut samples=0;let mut summaries=0;let rounds=a[3].to_str().unwrap().parse::<usize>().unwrap();
 for line in output.lines(){if let Some(s)=line.strip_prefix("SAMPLE "){let mut v:Value=serde_json::from_str(s).unwrap();if engine=="aeglos"{assert_eq!(v["cache_hit"],true);v["ms"]=v["verified_ms"].clone();}assert_eq!(v["round"].as_u64().unwrap(),samples);println!("SAMPLE {v}");samples+=1;}else if let Some(s)=line.strip_prefix("SUMMARY "){let mut v:Value=serde_json::from_str(s).unwrap();let n=workers.parse::<u64>().unwrap();if engine=="aeglos"{assert_eq!(v["threads"].as_u64().unwrap(),n);v["workers"]=n.into();}else{assert_eq!(v["workers"].as_u64().unwrap(),n);assert_eq!(v["priming"],3);}assert_eq!(v["rounds"].as_u64().unwrap(),rounds as u64);println!("SUMMARY {v}");summaries+=1;}}assert_eq!(samples,rounds as u64);assert_eq!(summaries,1);}
